import hashlib,json,subprocess,urllib.request
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parents[2]
source=json.loads((P/'incoming-source.json').read_text());changed=[name for name,sha in source.items() if not (R/name).is_file() or hashlib.sha256((R/name).read_bytes()).hexdigest()!=sha];assert changed==[],changed
snap=json.loads((P/'snapshot.json').read_text());assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=R).decode().strip()==snap['HEAD'];assert subprocess.check_output(['git','branch','--show-current'],cwd=R).decode().strip()==snap['branch'];assert '\nactive_run: NONE\n' in (R/'docs/task33/implementation-status.md').read_text()
server=json.loads((P/'server.json').read_text());assert str(P/'runtime.py').encode() in (Path('/proc')/str(server['pid'])/'cmdline').read_bytes();runtime=json.load(urllib.request.urlopen(server['url']+'/qa/start-version/',timeout=10));assert runtime['testing'] and runtime['entry_matches_startup'] and runtime['startup_matches_disk'];(P/'runtime-final.json').write_text(json.dumps(runtime,indent=2))
a=json.loads((P/'recheck.result.attempt1791962791.json').read_text());b=json.loads((P/'correction.result.json').read_text());assert not a.get('error') and not b.get('error');assert not a['errors'] and not b['errors'];assert not a['network'] and not b['network'];rows=a['rows']+b['rows'];fails=[r['id'] for r in rows if r['status']=='FAIL'];assert len(rows)==17 and len(fails)==6 and all(x.startswith('final-decline-owner-evidence-') for x in fails)
d=json.loads((P/'readback-declined.json').read_text());assert d['candidate_status']=='declined' and d['candidate_note'] and d['candidate_payload']['description_az']=='PROPOSED final decline OFFER08';assert d['program_live_description']==d['branch_snapshot_description']=='APPROVED original OFFER08'
b=json.loads((P/'readback-approved.json').read_text());assert b['candidate_status']=='approved' and b['program_live_description']==b['branch_snapshot_description']=='CORRECTED approved OFFER08';assert b['local_activity_name']=='Local OFFER08 activity'
for name in ['declined-readback','approved-readback','server','prepare-resume']:assert json.loads((P/(name+'.command.json')).read_text())['exit']==0
png=[{'file':'screenshots/'+f.name,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()} for f in sorted((P/'screenshots').glob('*.png'))];assert len(png)==10;(P/'png-manifest.json').write_text(json.dumps(png,indent=2))
q=subprocess.run(['git','diff','--check'],cwd=R,capture_output=True,text=True);assert q.returncode==0,q.stdout+q.stderr
v={'id':'OFFER-QA-08','status':'CONFIRMED OPEN; PLAN awaits approval','source_changed':changed,'snapshot_preserved':True,'runtime_source_match':True,'native_checks':17,'prerequisite_checks_PASS':11,'reproduced_FAIL':6,'PNG':10,'return_resubmit_approve':'PASS','declined_reason_payload_retained_in_DB':'PASS','declined_live_unchanged':'PASS','targeted_backend_tests':'NOT RUN (PLAN ONLY)','full_ACCEPT05':'NOT RUN','external':'BLOCKED / NOT RUN','production':'NOT RUN'};(P/'verification.json').write_text(json.dumps(v,indent=2));(P/'worktree-final.txt').write_text(subprocess.check_output(['git','status','--short'],cwd=R).decode());print(json.dumps(v))
